{
    void M1(C c1)
    {
        int x, y;
        _ = c1?.MA(c1.MB(out x, out y)) ?? false
            ? x.ToString()
            : y.ToString(); // 1
    }

    void M2(C c1)
    {
        int x, y;
        _ = c1?.MA(c1?.MB(out x, out y)) ?? false
            ? x.ToString() // 2
            : y.ToString(); // 3
    }

    bool MA(object obj) { return true; }
    C MB(out int x, out int y) { x = 42; y = 42; return this; }
}

